// Procesar datos de ambos competidores
const results = [];
const scrapedAt = new Date().toISOString();

// Procesar cada item recibido de ambos competidores
for (const item of $input.all()) {
  const data = item.json;

  // Determinar el competidor basado en el origen
  let competitorId = 'unknown';

  // Verificar si viene de fakestoreapi
  if (item.json.url && item.json.url.includes('fakestoreapi.com')) {
    competitorId = 'fakestore';
  } 
  // Verificar si viene de dummyjson
  else if (item.json.url && item.json.url.includes('dummyjson.com')) {
    competitorId = 'dummyjson';
  }
  // Verificar en los datos del producto
  else if (data.url && data.url.includes('fakestoreapi.com')) {
    competitorId = 'fakestore';
  }
  else if (data.url && data.url.includes('dummyjson.com')) {
    competitorId = 'dummyjson';
  }
  else if (data.image && data.image.includes('fakestoreapi.com')) {
    competitorId = 'fakestore';
  }
  else if (data.thumbnail && data.thumbnail.includes('dummyjson.com')) {
    competitorId = 'dummyjson';
  }
  else {
    competitorId = data.competitor_id || 'unknown';
  }

  // Procesar productos según el formato de la API
  if (Array.isArray(data)) {
    for (const product of data) {
      results.push({
        json: {
          name: product.name || product.title || 'Unknown Product',
          price: product.price || 0,
          category: product.category || 'general',
          competitor_id: competitorId,
          url: product.url || product.image || '',
          scraped_at: scrapedAt
        }
      });
    }
  } else if (data.products && Array.isArray(data.products)) {
    for (const product of data.products) {
      results.push({
        json: {
          name: product.name || product.title || 'Unknown Product',
          price: product.price || 0,
          category: product.category || 'general',
          competitor_id: competitorId,
          url: product.url || product.image || '',
          scraped_at: scrapedAt
        }
      });
    }
  } else {
    results.push({
      json: {
        name: data.name || data.title || 'Unknown Product',
        price: data.price || 0,
        category: data.category || 'general',
        competitor_id: competitorId,
        url: data.url || data.image || '',
        scraped_at: scrapedAt
      }
    });
  }
}

// Devolver todos los productos juntos
return results;

// Obtener datos de productos del nodo anterior
const products = $input.all();

if (products.length === 0) {
  return [{ json: { message: "No products found for analysis" } }];
}

// Análisis de precios
let priceAnalysis = {
  total_products: products.length,
  avg_price: 0,
  min_price: Infinity,
  max_price: -Infinity,
  by_competitor: {},
  by_category: {}
};

let totalPrice = 0;

for (const item of products) {
  const product = item.json;
  const price = parseFloat(product.price) || 0;

  totalPrice += price;

  if (price < priceAnalysis.min_price) priceAnalysis.min_price = price;
  if (price > priceAnalysis.max_price) priceAnalysis.max_price = price;

  // Por competidor
  const competitor = product.competitor_id || 'unknown';
  if (!priceAnalysis.by_competitor[competitor]) {
    priceAnalysis.by_competitor[competitor] = { count: 0, avg_price: 0, total_price: 0 };
  }
  priceAnalysis.by_competitor[competitor].count++;
  priceAnalysis.by_competitor[competitor].total_price += price;

  // Por categoría
  const category = product.category || 'general';
  if (!priceAnalysis.by_category[category]) {
    priceAnalysis.by_category[category] = { count: 0, avg_price: 0, total_price: 0 };
  }
  priceAnalysis.by_category[category].count++;
  priceAnalysis.by_category[category].total_price += price;
}

priceAnalysis.avg_price = totalPrice / products.length;

// Calcular promedios por competidor y categoría
for (const competitor in priceAnalysis.by_competitor) {
  priceAnalysis.by_competitor[competitor].avg_price = 
    priceAnalysis.by_competitor[competitor].total_price / priceAnalysis.by_competitor[competitor].count;
}

for (const category in priceAnalysis.by_category) {
  priceAnalysis.by_category[category].avg_price = 
    priceAnalysis.by_category[category].total_price / priceAnalysis.by_category[category].count;
}

return [{ json: priceAnalysis }];

// Obtener la respuesta de Groq Analysis
const groqResponse = $input.first().json;

let processedData = {
  analysis_date: new Date().toISOString(),
  summary: "Analysis completed",
  trends: [],
  opportunities: [],
  threats: [],
  recommendations: []
};

// Procesar la respuesta de Groq
if (groqResponse && groqResponse.choices && groqResponse.choices.length > 0) {
  try {
    const content = groqResponse.choices[0].message.content;

    // Intentar extraer JSON del contenido
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsedData = JSON.parse(jsonMatch[0]);

      processedData.summary = parsedData.summary || "Market intelligence analysis completed";

      // Extraer descripciones de los objetos y convertirlas a strings
      if (parsedData.trends && Array.isArray(parsedData.trends)) {
        processedData.trends = parsedData.trends.map(t => 
          typeof t === 'string' ? t : (t.descripcion || t.description || JSON.stringify(t))
        );
      }

      if (parsedData.opportunities && Array.isArray(parsedData.opportunities)) {
        processedData.opportunities = parsedData.opportunities.map(o => 
          typeof o === 'string' ? o : (o.descripcion || o.description || JSON.stringify(o))
        );
      }

      if (parsedData.threats && Array.isArray(parsedData.threats)) {
        processedData.threats = parsedData.threats.map(th => 
          typeof th === 'string' ? th : (th.descripcion || th.description || JSON.stringify(th))
        );
      }

      if (parsedData.recommendations && Array.isArray(parsedData.recommendations)) {
        processedData.recommendations = parsedData.recommendations.map(r => 
          typeof r === 'string' ? r : (r.descripcion || r.description || JSON.stringify(r))
        );
      }
    } else {
      processedData.summary = content.substring(0, 500) + (content.length > 500 ? "..." : "");
    }
  } catch (e) {
    console.log("Error parsing Groq response:", e);
    processedData.summary = "Error processing analysis results";
  }
}

return [{ json: processedData }];

// Obtener datos del análisis anterior
const analysisData = $input.first().json;

let priority = 'medium';
let message = 'Market Intelligence analysis completed';

// Función para extraer texto de objetos
const extractText = (item) => {
  if (typeof item === 'string') return item;
  if (item.descripcion) return item.descripcion;
  if (item.description) return item.description;
  if (item.nombre) return item.nombre;
